// ============================================================================
// FACEBOOK AD LIBRARY API - PARSE & FILTER RESULTS
// Updated: Feb 11, 2026
// Purpose: Parse Facebook API response and filter for relevant businesses
// ============================================================================

const response = $input.first().json;
const items = [];

try {
  // ===== STEP 1: ERROR HANDLING =====
  if (response.error) {
    const errorMsg = response.error.error_user_msg || response.error.message || 'Unknown API error';
    console.error('Facebook API Error:', errorMsg, 'Code:', response.error.code);
    return [{ 
      json: { 
        error: true, 
        errorMessage: errorMsg,
        errorCode: response.error.code,
        errorType: response.error.type
      } 
    }];
  }

  // ===== STEP 2: GET ADS FROM FACEBOOK API RESPONSE =====
  const ads = response.data || [];

  if (!Array.isArray(ads) || ads.length === 0) {
    console.log('No ads found for this search term');
    return [{ json: { noResults: true } }];
  }

  console.log(`Processing ${ads.length} ads from Facebook Ad Library API`);

  // ===== STEP 3: DEFINE FILTER KEYWORDS =====

  // ❌ EXCLUDE: Pages/content to filter OUT (irrelevant businesses)
  const EXCLUDE_KEYWORDS = [
    // Entertainment/Content
    'novel', 'reading', 'drama', 'story', 'fiction', 'tale', 'book',
    'read now', 'chapter', 'episode', 'series', 'flipreels',

    // Gaming/Apps
    'game', 'gaming', 'play now', 'download', 'app',

    // News/Media
    'news', 'media', 'channel', 'tv', 'video streaming',

    // Other
    'astrology', 'horoscope', 'predictions', 'fortune'
  ];

  // ✅ INCLUDE: Keywords that indicate REAL clothing/fashion businesses
  const CLOTHING_INDICATORS = [
    // Products
    'saree', 'kurti', 'lehenga', 'salwar', 'dupatta', 'suit',
    'dress', 'top', 'bottom', 'jeans', 'shirt', 'blouse',

    // Business Types
    'boutique', 'fashion', 'ethnic', 'designer', 'wear', 'collection',
    'store', 'shop', 'showroom', 'emporium',

    // Descriptors
    'ladies', 'women', 'mens', 'kids', 'bridal', 'party',
    'wedding', 'festive', 'casual', 'formal',

    // Shopping Terms
    'price', 'off', 'sale', 'discount', 'offer', 'deal',
    'cod', 'delivery', 'shipping', 'order'
  ];

  // ===== STEP 4: PROCESS EACH AD WITH FILTERING =====

  for (const ad of ads) {
    // Skip invalid entries
    if (!ad || typeof ad !== 'object' || !ad.id) {
      continue;
    }

    // --- FILTERING LOGIC STARTS HERE ---

    // Combine page name and ad bodies for text analysis
    const pageName = (ad.page_name || '').toLowerCase();
    const adBodies = (ad.ad_creative_bodies || []).join(' ').toLowerCase();
    const allText = pageName + ' ' + adBodies;

    // CHECK 1: Exclude irrelevant pages (novels, games, etc.)
    let shouldExclude = false;
    for (const keyword of EXCLUDE_KEYWORDS) {
      if (pageName.includes(keyword.toLowerCase()) || 
          adBodies.includes(keyword.toLowerCase())) {
        shouldExclude = true;
        console.log(`❌ Excluded: "${ad.page_name}" - Contains "${keyword}"`);
        break;
      }
    }

    if (shouldExclude) {
      continue; // Skip this ad
    }

    // CHECK 2: Must contain at least ONE clothing indicator
    let hasClothingIndicator = false;
    for (const keyword of CLOTHING_INDICATORS) {
      if (allText.includes(keyword.toLowerCase())) {
        hasClothingIndicator = true;
        break;
      }
    }

    if (!hasClothingIndicator) {
      console.log(`⚠️  Filtered: "${ad.page_name}" - No clothing indicators found`);
      continue; // Skip this ad
    }

    // --- FILTERING PASSED - PROCESS THIS AD ---

    console.log(`✅ Accepted: "${ad.page_name}"`);

    // Extract landing URL from captions (Facebook API structure)
    let landingUrl = '';
    if (Array.isArray(ad.ad_creative_link_captions) && ad.ad_creative_link_captions.length > 0) {
      const urlRegex = /(https?:\/\/[^\s]+)/gi;
      for (const caption of ad.ad_creative_link_captions) {
        const match = caption.match(urlRegex);
        if (match && match[0]) {
          landingUrl = match[0];
          break;
        }
      }
    }

    // Fallback to snapshot URL if no landing URL found
    if (!landingUrl) {
      landingUrl = ad.ad_snapshot_url || '';
    }

    // Normalize Facebook API response to expected format
    items.push({
      json: {
        // Core identifiers
        page_id: ad.page_id || 'unknown',
        page_name: ad.page_name || 'Unknown Business',
        ad_id: ad.id || String(Date.now()),

        // Ad content
        ad_snapshot_url: ad.ad_snapshot_url || '',
        ad_creative_bodies: ad.ad_creative_bodies || [],
        ad_creative_link_url: landingUrl,

        // Timing
        ad_delivery_start_time: ad.ad_delivery_start_time || null,
        ad_delivery_stop_time: ad.ad_delivery_stop_time || null,

        // Additional data
        currency: ad.currency || 'INR',
        spend: ad.spend || null,
        scraped_at: new Date().toISOString(),

        // Filtering metadata (for debugging)
        filter_passed: true,
        search_term_used: $input.first().json.searchTerm || 'unknown'
      }
    });
  }

  // ===== STEP 5: RETURN RESULTS =====

  if (items.length === 0) {
    console.log('⚠️  All ads filtered out - no relevant businesses found');
    return [{ json: { noResults: true, reason: 'All ads filtered as irrelevant' } }];
  }

  console.log(`✅ Successfully processed ${items.length} relevant ads (filtered from ${ads.length} total)`);
  return items;

} catch (error) {
  console.error('Parse error:', error.message, error.stack);
  return [{ 
    json: { 
      error: true, 
      errorMessage: `Parse error: ${error.message}`,
      errorStack: error.stack
    } 
  }];
}

const ads = $input.all();
const pageMap = new Map();

for (const item of ads) {
  const ad = item.json;
  const pid = ad.page_id;

  if (!pid || pid === 'unknown') continue;

  if (!pageMap.has(pid)) {
    pageMap.set(pid, {
      page_id: pid,
      page_name: ad.page_name,
      ad_count: 0,
      sample_ad: ad,
      earliest_start: ad.ad_delivery_start_time,
      all_bodies: [],
      landing_url: ad.ad_creative_link_url || ad.ad_snapshot_url
    });
  }

  const page = pageMap.get(pid);
  page.ad_count++;

  if (ad.ad_delivery_start_time) {
    if (!page.earliest_start || ad.ad_delivery_start_time < page.earliest_start) {
      page.earliest_start = ad.ad_delivery_start_time;
    }
  }

  if (Array.isArray(ad.ad_creative_bodies)) {
    page.all_bodies.push(...ad.ad_creative_bodies);
  }
}

const output = [];
for (const [pid, page] of pageMap.entries()) {
  output.push({ json: page });
}

return output.length > 0 ? output : [{ json: { noPages: true } }];

