const WA = /(api\.whatsapp\.com\/send|wa\.me\/|\bwhatsapp\b|click\.to\.whatsapp)/gi;
const JP = /\b(jaipur|pink city)\b/gi;
const PX = /(fbq\(|fbevents)/gi;
const CTWA = /(click\.to\.whatsapp)/gi;

function check(txt, rx) {
  if (!txt) return false;
  try { return rx.test(txt); } catch(e) { return false; }
}

function join(arr) {
  return Array.isArray(arr) ? arr.filter(x => x).join(' ') : '';
}

const allText = [pd.page_name || '', join(pd.all_bodies), html].join(' ');

const hasWA = check(allText, WA);
